#!/bin/bash

# Token Manager 确定性部署脚本 (使用CREATE)
# 部署TokenManagerProxy到固定地址（依赖固定私钥和nonce）

set -e  # 遇到错误立即退出

echo "🎯 Token Manager 部署脚本 (使用CREATE)"
echo "================================"

# ========== 配置参数 ==========
PRIVATE_KEY="0x9935c242a0b0ee41edcbd2d963f5bc7f142fdc803eb24f0df396a6fdb16c6af9"
RPC_URL="http://localhost:8123"
# 使用部署者地址作为Owner/Admin，确保权限一致
OWNER_ADMIN="0xDE282DC882bbB5100b8A24E30D38a2D5B3080c15"

echo "📝 部署参数:"
echo "  RPC URL: $RPC_URL"
echo "  Owner/Admin: $OWNER_ADMIN"
echo ""

# ========== 获取合约字节码 ==========
echo "📦 准备合约字节码..."

# 合约字节码 (已编译)
# TokenManagerConfigV1 字节码 (已编译)
IMPL_BYTECODE=""

# TokenManagerProxy 字节码 (已编译) 
PROXY_BYTECODE=""

if [ ${#IMPL_BYTECODE} -le 100 ] || [ ${#PROXY_BYTECODE} -le 100 ]; then
    echo "❌ 错误: 合约字节码太短，请先编译合约获取真实字节码"
    echo "💡 执行以下命令编译合约:"
    echo "   solc --bin contracts/TokenManagerConfigV1.sol"
    echo "   solc --bin contracts/TokenManagerProxy.sol"
    exit 1
fi

echo "📦 实现合约字节码长度: ${#IMPL_BYTECODE} 字符"
echo "📦 代理合约字节码长度: ${#PROXY_BYTECODE} 字符"
echo ""

# ========== 部署实现合约 ==========
echo "🚀 Step 1: 部署实现合约..."

echo "📦 部署实现合约 (使用标准CREATE)..."
IMPL_DEPLOY_RESULT=$(cast send --private-key $PRIVATE_KEY --rpc-url $RPC_URL --legacy --create $IMPL_BYTECODE)

if [ $? -eq 0 ]; then
    echo "⏳ 等待实现合约部署确认..."
    sleep 3

    # 从部署结果提取地址
    IMPL_ADDRESS=$(echo "$IMPL_DEPLOY_RESULT" | grep "contractAddress" | awk '{print $2}')

    if [ -n "$IMPL_ADDRESS" ] && [ "$IMPL_ADDRESS" != "null" ]; then
        echo "✅ 实现合约部署成功！"
        echo "📍 实现合约地址: $IMPL_ADDRESS"
    else
        echo "❌ 无法获取实现合约地址"
        exit 1
    fi
else
    echo "❌ 实现合约部署失败"
    exit 1
fi

echo ""

# ========== 部署代理合约 ==========
echo "🚀 Step 2: 部署代理合约 (使用CREATE)..."

# 编码代理合约构造函数参数
PROXY_CONSTRUCTOR=$(cast abi-encode "constructor(address,address,bytes)" $IMPL_ADDRESS $OWNER_ADMIN "0x")

if [ ${#PROXY_CONSTRUCTOR} -le 2 ]; then
    echo "❌ 无法编码代理合约构造函数参数"
    exit 1
fi

# 构造完整的代理合约部署数据
PROXY_DEPLOY_DATA="${PROXY_BYTECODE}${PROXY_CONSTRUCTOR:2}"

# 部署代理合约
echo "📦 部署代理合约..."
PROXY_DEPLOY_RESULT=$(cast send --private-key $PRIVATE_KEY --rpc-url $RPC_URL --legacy --create $PROXY_DEPLOY_DATA)

if [ $? -eq 0 ]; then
    echo "⏳ 等待代理合约部署确认..."
    sleep 3

    # 从部署结果提取地址
    PROXY_ADDRESS=$(echo "$PROXY_DEPLOY_RESULT" | grep "contractAddress" | awk '{print $2}')

    if [ -n "$PROXY_ADDRESS" ] && [ "$PROXY_ADDRESS" != "null" ]; then
        echo "✅ 代理合约部署成功！"
        echo "📍 代理合约地址: $PROXY_ADDRESS"
    else
        echo "❌ 无法获取代理合约地址"
        exit 1
    fi
else
    echo "❌ 代理合约部署失败"
    exit 1
fi

echo ""

# ========== 初始化配置 ==========
echo "🔧 Step 3: 初始化合约配置..."

# 初始化实现合约
echo "🔧 初始化实现合约..."
INIT_TX=$(cast send $PROXY_ADDRESS \
    "initialize(address)" \
    $OWNER_ADMIN \
    --private-key $PRIVATE_KEY \
    --rpc-url $RPC_URL \
    --legacy)

if [ $? -eq 0 ]; then
    echo "⏳ 等待初始化确认..."
    sleep 2
    echo "✅ 合约初始化成功"
else
    echo "⚠️  合约初始化失败，可能已经初始化过"
fi

# 激活Token Manager (设置激活区块为当前区块+1)
CURRENT_BLOCK=$(cast block-number --rpc-url $RPC_URL)
ACTIVATION_BLOCK=$((CURRENT_BLOCK + 1))

echo "🔧 设置激活区块: $ACTIVATION_BLOCK"
ACTIVATE_TX=$(cast send $PROXY_ADDRESS \
    "setActivationBlock(uint256)" \
    $ACTIVATION_BLOCK \
    --private-key $PRIVATE_KEY \
    --rpc-url $RPC_URL \
    --legacy)

if [ $? -eq 0 ]; then
    echo "⏳ 等待激活设置确认..."
    sleep 2
    echo "✅ 激活区块设置成功"
else
    echo "❌ 激活区块设置失败"
fi

echo ""

# ========== 验证部署 ==========
echo "🔍 Step 4: 验证部署结果..."

# 验证代理合约
echo "🔍 验证代理合约..."
IMPL_FROM_PROXY=$(cast call $PROXY_ADDRESS "implementation()" --rpc-url $RPC_URL)
ADMIN_FROM_PROXY=$(cast call $PROXY_ADDRESS "admin()" --rpc-url $RPC_URL)

echo "📋 代理合约验证:"
echo "   代理地址: $PROXY_ADDRESS"
echo "   实现地址: $IMPL_FROM_PROXY"
echo "   管理员: $ADMIN_FROM_PROXY"

# 验证配置合约功能
echo "🔍 验证配置合约功能..."
IS_ACTIVE=$(cast call $PROXY_ADDRESS "isActive()" --rpc-url $RPC_URL)
OWNER=$(cast call $PROXY_ADDRESS "owner()" --rpc-url $RPC_URL)
ACTIVATION_BLOCK_SET=$(cast call $PROXY_ADDRESS "activationBlock()" --rpc-url $RPC_URL)

echo "📋 配置合约验证:"
echo "   是否激活: $IS_ACTIVE"
echo "   所有者: $OWNER"
echo "   激活区块: $ACTIVATION_BLOCK_SET"

echo ""

# ========== 部署总结 ==========
echo "📋 部署总结"
echo "============"
echo "✅ 部署完成时间: $(date)"
echo "📍 实现合约: $IMPL_ADDRESS"
echo "📍 代理合约: $PROXY_ADDRESS"
echo "👤 管理员: $OWNER_ADMIN"

echo "🎉 代理合约已部署！"
echo "💡 记录代理合约地址: $PROXY_ADDRESS"
echo "💡 为确保每次部署地址一致，请保证："
echo "   1. 使用相同 PRIVATE_KEY"
echo "   2. 部署前重置网络或确保 nonce 一致（例如 nonce=0）"

echo ""
echo "📋 下一步操作:"
echo "1. 测试Token Manager功能:"
echo "   # Mint 1 ETH to test address"
echo "   cast send 0x0000000000000000000000000000000000000101 \\"
echo "     '0x01000000000000000000000000test_address0de0b6b3a7640000' \\"
echo "     --private-key $PRIVATE_KEY --rpc-url $RPC_URL --legacy"
echo ""
echo "2. 管理白名单:"
echo "   cast send $PROXY_ADDRESS 'addBurnWhitelist(address)' test_address --private-key $PRIVATE_KEY --rpc-url $RPC_URL --legacy"

echo ""
echo "✅ Token Manager 部署完成！🎉"